/* ---------- Gauge de margem ---------- */
function Gauge({ value }) {
  const clamped = Math.max(0, Math.min(value, 0.6));
  const angle = -180 + (clamped / 0.6) * 180;
  const color = value >= 0.3 ? ACID_GREEN_DARK : value >= 0.2 ? "#E7A100" : RED;
  const arc = (start, end, stroke) => {
    const r = 70, cx = 90, cy = 90;
    const p = (a) => [cx + r * Math.cos((a * Math.PI) / 180), cy + r * Math.sin((a * Math.PI) / 180)];
    const [x1, y1] = p(start), [x2, y2] = p(end);
    return <path d={`M ${x1} ${y1} A ${r} ${r} 0 0 1 ${x2} ${y2}`} stroke={stroke} strokeWidth="14" fill="none" strokeLinecap="butt" />;
  };
  return (
    <svg viewBox="0 0 180 100" className="w-full max-w-[260px] mx-auto">
      {arc(-180, -120, "#FCD9DA")}
      {arc(-120, -90, "#FCEEC9")}
      {arc(-90, 0, "#CFF5E3")}
      <line
        x1="90" y1="90"
        x2={90 + 55 * Math.cos((angle * Math.PI) / 180)}
        y2={90 + 55 * Math.sin((angle * Math.PI) / 180)}
        stroke="#111" strokeWidth="3" strokeLinecap="round"
      />
      <circle cx="90" cy="90" r="5" fill="#111" />
      <text x="90" y="70" textAnchor="middle" fontSize="20" fontWeight="700" fill={color}>{pct(value)}</text>
    </svg>
  );
}

/* ============================================================
   APP
   ============================================================ */
export default function AcidFinance() {
  const [tab, setTab] = useState("dashboard");
  const [proj, setProj] = useState(PROJETO_ATTO);
  const [externos, setExternos] = useState(EXTERNOS_ATTO);
  const [internos, setInternos] = useState(INTERNOS_ATTO);
  const [cronograma, setCronograma] = useState(CRONOGRAMA_ATTO);
  const [blocos, setBlocos] = useState(BLOCOS_PADRAO);
  const [aviso, setAviso] = useState("");
  const fileRef = useRef(null);

  const exportJSON = () => {
    const payload = {
      app: "acid-finance", versao: 1, salvoEm: new Date().toISOString(),
      proj, externos, internos, cronograma, blocos,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${proj.cliente}_${proj.numeroServico}_${proj.projeto}`.replace(/\s+/g, "-") + ".json";
    a.click();
    URL.revokeObjectURL(url);
    setAviso("Projeto salvo em JSON — guarde o arquivo.");
  };

  const importJSON = (file) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const d = JSON.parse(reader.result);
        if (!d.proj || !Array.isArray(d.externos) || !Array.isArray(d.internos)) {
          throw new Error("estrutura inválida");
        }
        setProj({ ...PROJETO_ATTO, ...d.proj });
        setExternos(d.externos);
        setInternos(d.internos);
        setCronograma(Array.isArray(d.cronograma) ? d.cronograma : []);
        setBlocos({ ...BLOCOS_PADRAO, ...(d.blocos || {}) });
        setAviso(`Carregado: ${file.name}`);
      } catch (err) {
        setAviso("Não foi possível ler este arquivo. Use um JSON exportado pelo ACID Finance.");
      }
    };
    reader.readAsText(file);
  };

  const dre = useMemo(
    () => computeDRE({ ...proj, externos, internos }),
    [proj, externos, internos]
  );

  const setP = (k, v) => setProj((p) => ({ ...p, [k]: v }));

  const tabs = [
    ["dashboard", "Dashboard"],
    ["projeto", "Projeto"],
    ["pessoas", "Pessoas & Custos"],
    ["dre", "DRE"],
    ["simulador", "Simulador"],
    ["orcamento", "Orçamento"],
  ];

  return (
    <div className="min-h-screen bg-neutral-100 text-neutral-900" style={{ fontFamily: "'Inter', system-ui, sans-serif" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Libre+Caslon+Display&family=Libre+Caslon+Text:ital,wght@0,400;0,700;1,400&display=swap');`}</style>
      {/* Header */}
      <header className="bg-neutral-950 text-white">
        <div className="max-w-6xl mx-auto px-5 py-4 flex flex-wrap items-center gap-4 justify-between">
          <div className="flex items-baseline gap-3">
            <img src={LOGO_ACID} alt="ACID" className="h-7 w-auto" />
            <span className="text-xl text-white leading-none uppercase tracking-[0.18em]" style={{ fontFamily: "'Libre Caslon Display', 'Libre Caslon Text', serif", fontWeight: 300 }}>Finance</span>
            <span className="text-xs text-neutral-400 hidden sm:inline">salve e carregue o projeto em JSON</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-neutral-300 tabular-nums hidden md:inline">
              {proj.cliente} · {proj.projeto} · {proj.numeroServico}
            </span>
            <button
              onClick={() => fileRef.current?.click()}
              className="text-xs px-3 py-1.5 rounded-md border border-neutral-600 text-neutral-200 hover:border-neutral-400 hover:text-white"
            >
              Carregar JSON
            </button>
            <button
              onClick={exportJSON}
              className="text-xs px-3 py-1.5 rounded-md font-semibold text-neutral-900"
              style={{ background: ACID_GREEN }}
            >
              Salvar JSON
            </button>
            <input
              ref={fileRef} type="file" accept=".json,application/json" className="hidden"
              onChange={(e) => { importJSON(e.target.files?.[0]); e.target.value = ""; }}
            />
          </div>
        </div>
        <nav className="max-w-6xl mx-auto px-5 flex gap-1 overflow-x-auto">
          {tabs.map(([id, label]) => (
            <button
              key={id}
              onClick={() => setTab(id)}
              className={`px-4 py-2.5 text-sm whitespace-nowrap border-b-2 transition-colors ${
                tab === id ? "border-emerald-400 text-white font-medium" : "border-transparent text-neutral-400 hover:text-white"
              }`}
            >
              {label}
            </button>
          ))}
        </nav>
      </header>

      <main className="max-w-6xl mx-auto px-5 py-6 space-y-5">
        {aviso && (
          <div className="text-xs px-3 py-2 rounded-md bg-emerald-50 border border-emerald-200 text-emerald-800 flex justify-between items-center">
            <span>{aviso}</span>
            <button onClick={() => setAviso("")} className="text-emerald-600 hover:text-emerald-900 ml-3">×</button>
          </div>
        )}
        {tab === "dashboard" && <Dashboard dre={dre} proj={proj} />}
        {tab === "projeto" && <ProjetoForm proj={proj} setP={setP} />}
        {tab === "pessoas" && (
          <Pessoas
            externos={externos} setExternos={setExternos}
            internos={internos} setInternos={setInternos}
            dre={dre} proj={proj}
          />
        )}
        {tab === "dre" && <DREPage dre={dre} proj={proj} />}
        {tab === "simulador" && <Simulador base={{ proj, externos, internos }} />}
        {tab === "orcamento" && (
          <Orcamento proj={proj} setP={setP} dre={dre} cronograma={cronograma} setCronograma={setCronograma} blocos={blocos} setBlocos={setBlocos} />
        )}
      </main>

      <footer className="max-w-6xl mx-auto px-5 pb-8 text-xs text-neutral-400">
        Protótipo — os dados vivem no arquivo JSON: salve após editar e carregue para retomar. PDF do DRE, CSV e multi-projetos entram na versão Next.js.
      </footer>
    </div>
  );
}

