/* ============================================================
   SIMULADOR
   ============================================================ */
function Simulador({ base }) {
  const [sim, setSim] = useState({
    valorBruto: base.proj.valorBruto,
    impostosPct: base.proj.impostosPct,
    comissaoPct: base.proj.comissaoPct,
    overheadPct: base.proj.overheadPct,
    custosExternos: base.externos.reduce((s, e) => s + e.valor, 0),
    horasFator: 100, // % das horas internas originais
    margemDesejada: 30,
  });
  const set = (k, v) => setSim((s) => ({ ...s, [k]: v }));

  const internosSim = base.internos.map((p) => ({ ...p, horasProjeto: p.horasProjeto * (sim.horasFator / 100) }));
  const dre = computeDRE({
    valorBruto: sim.valorBruto,
    impostosPct: sim.impostosPct,
    comissaoPct: sim.comissaoPct,
    overheadPct: sim.overheadPct,
    externos: [{ valor: sim.custosExternos }],
    internos: internosSim,
  });

  const alvos = [20, 25, 30, 35, 40];
  const minRecomendado = valorParaMargem(sim.margemDesejada / 100, dre.custoTotal, sim.impostosPct, sim.comissaoPct);

  return (
    <div className="grid lg:grid-cols-2 gap-5">
      <Section title="Variáveis da simulação">
        <div className="grid sm:grid-cols-2 gap-4">
          <Field label="Valor de venda (R$)"><NumInput value={sim.valorBruto} onChange={(v) => set("valorBruto", v)} /></Field>
          <Field label="Custos externos (R$)"><NumInput value={sim.custosExternos} onChange={(v) => set("custosExternos", v)} /></Field>
          <Field label="Impostos (%)"><NumInput value={sim.impostosPct} onChange={(v) => set("impostosPct", v)} /></Field>
          <Field label="Comissão (%)"><NumInput value={sim.comissaoPct} onChange={(v) => set("comissaoPct", v)} /></Field>
          <Field label="Overhead (%)"><NumInput value={sim.overheadPct} onChange={(v) => set("overheadPct", v)} /></Field>
          <Field label="Horas internas (% do plano)"><NumInput value={sim.horasFator} onChange={(v) => set("horasFator", v)} /></Field>
          <Field label="Margem desejada (%)"><NumInput value={sim.margemDesejada} onChange={(v) => set("margemDesejada", v)} /></Field>
        </div>
        <p className="text-xs text-neutral-400 mt-4">A simulação não altera o projeto — é uma cópia em memória.</p>
      </Section>

      <div className="space-y-5">
        <div className="grid grid-cols-2 gap-3">
          <KPI label="Lucro resultante" value={fmt(dre.lucroOperacional)} tone={dre.lucroOperacional >= 0 ? "pos" : "neg"} />
          <KPI label="Margem operacional" value={pct(dre.margemOperacional)} tone={dre.margemOperacional >= 0.3 ? "pos" : dre.margemOperacional >= 0.2 ? undefined : "neg"} />
          <KPI label="Custo total" value={fmt(dre.custoTotal)} />
          <KPI label={`Mínimo p/ ${sim.margemDesejada}% de margem`} value={fmt(minRecomendado)} tone="pos" />
        </div>

        <Section title="Valor de venda por margem-alvo">
          <table className="w-full text-sm">
            <thead><tr className="border-b border-neutral-200 text-[11px] uppercase tracking-widest text-neutral-500">
              <th className="text-left py-2">Margem operacional</th>
              <th className="text-right py-2">Valor de venda</th>
              <th className="text-right py-2">Lucro</th>
            </tr></thead>
            <tbody>
              {alvos.map((m) => {
                const v = valorParaMargem(m / 100, dre.custoTotal, sim.impostosPct, sim.comissaoPct);
                const ro = v * (1 - sim.impostosPct / 100) * (1 - sim.comissaoPct / 100);
                const atingido = sim.valorBruto >= v;
                return (
                  <tr key={m} className="border-b border-neutral-100">
                    <td className="py-2">
                      <span className={`inline-block w-2 h-2 rounded-full mr-2 ${atingido ? "bg-emerald-500" : "bg-neutral-300"}`} />
                      {m}%
                    </td>
                    <td className="py-2 text-right tabular-nums font-medium">{fmt(v)}</td>
                    <td className="py-2 text-right tabular-nums text-neutral-500">{fmt(ro - dre.custoTotal)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </Section>
      </div>
    </div>
  );
}


/* ============================================================
   GERADOR DE PDF DA PROPOSTA — sem dependências externas
   Constrói o PDF byte a byte (Helvetica/WinAnsi + logo em JPEG)
   ============================================================ */
const A4W = 595.28, A4H = 841.89, MARGIN = 56, CONTENT_W = A4W - MARGIN * 2;

const _pdfCanvas = typeof document !== "undefined" ? document.createElement("canvas") : null;
const _pdfCtx = _pdfCanvas ? _pdfCanvas.getContext("2d") : null;

const LATIN1_MAP = { "\u2013": "\x96", "\u2014": "\x97", "\u2018": "\x91", "\u2019": "\x92", "\u201C": "\x93", "\u201D": "\x94", "\u2022": "\x95", "\u2026": "\x85" };
function toLatin1(s) {
  let out = "";
  for (const ch of String(s)) {
    if (LATIN1_MAP[ch]) out += LATIN1_MAP[ch];
    else out += ch.charCodeAt(0) <= 255 ? ch : "?";
  }
  return out;
}
function escPdf(s) {
  return toLatin1(s).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}
function textWpt(text, size, bold) {
  if (!_pdfCtx) return String(text).length * size * 0.5;
  _pdfCtx.font = `${bold ? "bold " : ""}${size}px Helvetica, Arial, sans-serif`;
  return _pdfCtx.measureText(String(text)).width * 1.02; // 2% de folga
}
function wrapText(text, size, bold, maxW) {
  const lines = [];
  for (const raw of String(text ?? "").split("\n")) {
    if (!raw.trim()) { lines.push(""); continue; }
    let line = "";
    for (const word of raw.split(" ")) {
      const t = line ? line + " " + word : word;
      if (line && textWpt(t, size, bold) > maxW) { lines.push(line); line = word; }
      else line = t;
    }
    lines.push(line);
  }
  return lines;
}

function logoAsJpeg(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width = img.width; c.height = img.height;
      const ctx = c.getContext("2d");
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, c.width, c.height);
      ctx.drawImage(img, 0, 0);
      const b64 = c.toDataURL("image/jpeg", 0.92).split(",")[1];
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      resolve({ bytes, w: img.width, h: img.height });
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

function makeDoc() {
  const pages = [];
  let ops = [];
  let y = MARGIN;
  const newPage = () => { pages.push(ops); ops = []; y = MARGIN; };
  const ensure = (h) => { if (y + h > A4H - MARGIN) newPage(); };
  const raw = (s) => ops.push(s);
  const getY = () => y;
  const setY = (v) => { y = v; };
  const space = (h) => { ensure(h); y += h; };
  const text = (str, size, o = {}) => {
    const { bold = false, gray = false, x = MARGIN, maxW = CONTENT_W, lh = 1.5 } = o;
    const color = gray ? "0.45 0.45 0.45 rg" : "0 0 0 rg";
    for (const ln of wrapText(str, size, bold, maxW)) {
      ensure(size * lh);
      y += size * lh;
      if (!ln) continue;
      ops.push(`BT /${bold ? "F2" : "F1"} ${size} Tf ${color} ${x.toFixed(2)} ${(A4H - y).toFixed(2)} Td (${escPdf(ln)}) Tj ET`);
    }
  };
  const rule = (weight = 1) => {
    ensure(weight + 4);
    y += 3;
    ops.push(`${weight} w 0 0 0 RG ${MARGIN} ${(A4H - y).toFixed(2)} m ${(A4W - MARGIN).toFixed(2)} ${(A4H - y).toFixed(2)} l S`);
    y += weight + 1;
  };
  const image = (name, wPt, hPt) => {
    ensure(hPt);
    ops.push(`q ${wPt.toFixed(2)} 0 0 ${hPt.toFixed(2)} ${MARGIN} ${(A4H - y - hPt).toFixed(2)} cm /${name} Do Q`);
    y += hPt;
  };
  const finish = () => { pages.push(ops); return pages; };
  return { text, space, rule, image, raw, ensure, getY, setY, newPage, finish };
}

function assemblePdf(pages, logo) {
  const chunks = [];
  let pos = 0;
  const offsets = [];
  const pushStr = (s) => {
    const b = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i) & 0xff;
    chunks.push(b); pos += b.length;
  };
  const pushBytes = (b) => { chunks.push(b); pos += b.length; };

  const nPages = pages.length;
  const total = 5 + nPages * 2;
  const pageObj = (i) => 6 + i * 2;
  const contObj = (i) => 7 + i * 2;

  pushStr("%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n");
  const begin = (n) => { offsets[n] = pos; pushStr(`${n} 0 obj\n`); };
  const end = () => pushStr("endobj\n");

  begin(1); pushStr("<< /Type /Catalog /Pages 2 0 R >>\n"); end();
  begin(2); pushStr(`<< /Type /Pages /Count ${nPages} /Kids [${pages.map((_, i) => `${pageObj(i)} 0 R`).join(" ")}] >>\n`); end();
  begin(3); pushStr("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\n"); end();
  begin(4); pushStr("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>\n"); end();
  begin(5);
  if (logo) {
    pushStr(`<< /Type /XObject /Subtype /Image /Width ${logo.w} /Height ${logo.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logo.bytes.length} >>\nstream\n`);
    pushBytes(logo.bytes);
    pushStr("\nendstream\n");
  } else {
    pushStr("<< /Type /XObject /Subtype /Form /BBox [0 0 1 1] /Length 0 >>\nstream\n\nendstream\n");
  }
  end();

  pages.forEach((ops, i) => {
    begin(pageObj(i));
    pushStr(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${A4W} ${A4H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /X0 5 0 R >> >> /Contents ${contObj(i)} 0 R >>\n`);
    end();
    const stream = ops.join("\n");
    begin(contObj(i));
    pushStr(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream\n`);
    end();
  });

  const xrefPos = pos;
  pushStr(`xref\n0 ${total + 1}\n0000000000 65535 f \n`);
  for (let n = 1; n <= total; n++) pushStr(`${String(offsets[n]).padStart(10, "0")} 00000 n \n`);
  pushStr(`trailer\n<< /Size ${total + 1} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF`);

  return new Blob(chunks, { type: "application/pdf" });
}

async function gerarOrcamentoPDF({ proj, dre, cronograma, blocos }) {
  const logo = await logoAsJpeg(LOGO_ACID);
  const d = makeDoc();

  // Cabeçalho
  if (logo) d.image("X0", 118, (118 * logo.h) / logo.w);
  d.space(10);
  d.text("THE ACID TIMES LTDA", 10, { bold: true });
  d.text("CNPJ: 36.458.402/0001-81", 8, { gray: true });
  d.space(5);
  d.text(`Data: ${proj.data}     Cliente: ${proj.cliente}     Projeto: ${proj.projeto} (${proj.numeroServico})     Validade: ${proj.validadeProposta}`, 8, { gray: true });
  d.rule(1.4);
  d.space(12);
  d.text(proj.titulo, 15, { bold: true, lh: 1.3 });
  d.space(6);

  const bloco = (n, titulo, body) => {
    d.space(12);
    d.ensure(44); // evita título órfão no fim da página
    d.text(`${n}. ${titulo.toUpperCase()}`, 8, { bold: true, gray: true, lh: 1.4 });
    d.space(3);
    if (typeof body === "function") body();
    else d.text(body && String(body).trim() ? body : "—", 9.5, { lh: 1.5 });
  };

  bloco(1, "Projeto", `${proj.projeto} — ${proj.tipo} para ${proj.cliente}.`);
  bloco(2, "O serviço inclui", blocos.servicoInclui);
  bloco(3, "Especificação da entrega", blocos.entrega);

  bloco(4, "Investimento", () => {
    const h = 42;
    d.ensure(h + 18);
    const yTop = A4H - d.getY() - h;
    d.raw(`0.9 w 0 0 0 RG ${MARGIN} ${yTop.toFixed(2)} ${CONTENT_W.toFixed(2)} ${h} re S`);
    const cy = yTop + h / 2 - 4;
    d.raw(`BT /F1 9.5 Tf 0 0 0 rg ${(MARGIN + 14).toFixed(2)} ${cy.toFixed(2)} Td (${escPdf("Investimento total do projeto")}) Tj ET`);
    const val = fmt(dre.receitaBruta);
    const vw = textWpt(val, 15, true);
    d.raw(`BT /F2 15 Tf 0 0 0 rg ${(A4W - MARGIN - 14 - vw).toFixed(2)} ${cy.toFixed(2)} Td (${escPdf(val)}) Tj ET`);
    d.setY(d.getY() + h + 5);
    d.text("Valor bruto, impostos inclusos.", 7.5, { gray: true });
  });

  bloco(5, "Condições de pagamento", proj.condicaoPagamento);

  bloco(6, "Cronograma", () => {
    cronograma.forEach((m) => {
      const lines = wrapText(m.marco, 9.5, false, CONTENT_W - 74);
      lines.forEach((ln, idx) => {
        d.ensure(9.5 * 1.5);
        d.setY(d.getY() + 9.5 * 1.5);
        const yy = (A4H - d.getY()).toFixed(2);
        if (idx === 0) d.raw(`BT /F2 9.5 Tf 0 0 0 rg ${MARGIN} ${yy} Td (${escPdf(m.data)}) Tj ET`);
        d.raw(`BT /F1 9.5 Tf 0 0 0 rg ${(MARGIN + 74).toFixed(2)} ${yy} Td (${escPdf(ln)}) Tj ET`);
      });
    });
  });

  bloco(7, "Não está incluso", blocos.exclusoes);
  bloco(8, "Alterações e refações", blocos.alteracoes);
  bloco(9, "Observações", blocos.observacoes);
  bloco(10, "Imagens e limitações técnicas em IA", blocos.clausulaIA);
  bloco(11, "Materiais de apoio", blocos.materiais);
  bloco(12, "Validade", `Esta proposta é válida por ${proj.validadeProposta} a partir da data de emissão.`);

  const pages = d.finish();
  pages.forEach((ops, i) => {
    const label = `Página ${i + 1} de ${pages.length}`;
    const w = textWpt(label, 7, false);
    ops.push(`BT /F1 7 Tf 0.6 0.6 0.6 rg ${((A4W - w) / 2).toFixed(2)} 28 Td (${escPdf(label)}) Tj ET`);
  });

  const blob = assemblePdf(pages, logo);
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Orcamento_${proj.cliente}_${proj.numeroServico}`.replace(/\s+/g, "-") + ".pdf";
  a.click();
  URL.revokeObjectURL(url);
}

